int remount_shmem(struct super_block *sb, int *flags, const char *data) {
    struct shmem_config new_config = {0};
    char *copy_data = NULL;
    int ret = -EINVAL;

    if (!sb || !flags || !data) {
        return -EINVAL;
    }

    copy_data = kstrdup(data, GFP_KERNEL);
    if (!copy_data) {
        return -ENOMEM;
    }

    if (parse_shmem_options(copy_data, &new_config) < 0) {
        goto out;
    }

    if (new_config.max_blocks <= 0 || new_config.max_inodes <= 0) {
        goto out;
    }

    down_write(&shmem_remount_mutex);

    if (sb->s_maxbytes < new_config.max_bytes) {
        sb->s_maxbytes = new_config.max_bytes;
    }

    if (sb->s_maxinodes < new_config.max_inodes) {
        sb->s_maxinodes = new_config.max_inodes;
    }

    if (sb->s_blocksize != new_config.block_size) {
        sb->s_blocksize = new_config.block_size;
    }

    if (new_config.policy) {
        sb->s_policy = new_config.policy;
    }

    ret = 0;

    up_write(&shmem_remount_mutex);

out:
    kfree(copy_data);
    return ret;
}
